from pathlib import Path
p=Path('editor/Medieval_Battlefield_Editor_v4.py')
s=p.read_text(encoding='utf-8')
s=s.replace("('🛣 Дорога','road'),", "('🛣 Просёлочная','road_dirt'),('🪨 Мощенная','road_paved'),('⬜ Брусчаточная','road_cobble'),")
s=s.replace("TYPES=['Пехота'", "ROAD_TYPES=['Просёлочная','Мощенная','Брусчаточная']\n\nTYPES=['Пехота'")
s=s.replace("self.tool='select';self.brush=150", "self.tool='select';self.brush=150;self.road_type='Просёлочная'")
s=s.replace("self.objects.append({'id':self.oid(),'kind':'road','points':[a,m,b],'width':30})", "self.objects.append({'id':self.oid(),'kind':'road','road_type':r.choice(ROAD_TYPES),'points':[a,m,b],'width':30})")
s=s.replace("if self.tool in ('river','road'):", "if self.tool in ('river','road_dirt','road_paved','road_cobble'):")
s=s.replace("elif self.tool in ('river','road') and self.stroke is not None:", "elif self.tool in ('river','road_dirt','road_paved','road_cobble') and self.stroke is not None:")
s=s.replace("if self.tool in ('river','road') and self.stroke and len(self.stroke)>1:", "if self.tool in ('river','road_dirt','road_paved','road_cobble') and self.stroke and len(self.stroke)>1:")
s=s.replace("return {'version':5,", "return {'version':6,")
start=s.index('    def draw_line_obj(self,o):')
end=s.index('    def draw_obj(self,o):',start)
draw='''    def draw_line_obj(self,o):\n        p=self.pts(o['points']);wd=o.get('width',25)*self.scale\n        if o['kind']=='river':\n            self.canvas.create_line(*p,fill='#4b4238',width=max(8,int(wd+32*self.scale)),smooth=True,capstyle='round')\n            self.canvas.create_line(*p,fill='#4fa8a2',width=max(5,int(wd)),smooth=True,capstyle='round')\n            self.canvas.create_line(*p,fill='#8ccbc1',width=max(1,int(3*self.scale)),smooth=True,capstyle='round')\n        else:\n            rt=o.get('road_type','Просёлочная')\n            colors={'Просёлочная':('#624b37','#b79a70','#dbc79f'),'Мощенная':('#51483e','#756b5d','#b9ad96'),'Брусчаточная':('#4a3b2d','#8b7b67','#c5b69a')}\n            edge,surf,detail=colors.get(rt,colors['Просёлочная'])\n            self.canvas.create_line(*p,fill=edge,width=max(5,int(wd+12*self.scale)),smooth=True,capstyle='round')\n            self.canvas.create_line(*p,fill=surf,width=max(3,int(wd)),smooth=True,capstyle='round')\n            self.canvas.create_line(*p,fill=detail,width=max(1,int(wd*.13)),smooth=True,capstyle='round',dash=((2,5) if rt=='Брусчаточная' else (7,6) if rt=='Мощенная' else ()))\n\n    def line_segments(self,o):\n        pts=o.get('points',[]);return list(zip(pts,pts[1:]))\n\n    def closest_on_seg(self,p,a,b):\n        x,y=p;x1,y1=a;x2,y2=b;dx=x2-x1;dy=y2-y1\n        if dx==dy==0:return a,math.hypot(x-x1,y-y1)\n        t=max(0,min(1,((x-x1)*dx+(y-y1)*dy)/(dx*dx+dy*dy)));q=(x1+t*dx,y1+t*dy)\n        return q,math.hypot(x-q[0],y-q[1])\n\n    def snap_line_endpoints(self,kind,points):\n        out=list(points);threshold=130 if kind=='river' else 90\n        for idx in (0,-1):\n            best=None\n            for o in self.objects:\n                if o.get('kind')!=kind:continue\n                for a,b in self.line_segments(o):\n                    q,d=self.closest_on_seg(out[idx],a,b)\n                    if d<=threshold and (best is None or d<best[0]):best=(d,q)\n            if best:out[idx]=best[1]\n        return out\n\n    def seg_intersection(self,a,b,c,d):\n        x1,y1=a;x2,y2=b;x3,y3=c;x4,y4=d;den=(x1-x2)*(y3-y4)-(y1-y2)*(x3-x4)\n        if abs(den)<1e-9:return None\n        px=((x1*y2-y1*x2)*(x3-x4)-(x1-x2)*(x3*y4-y3*x4))/den\n        py=((x1*y2-y1*x2)*(y3-y4)-(y1-y2)*(x3*y4-y3*x4))/den\n        if min(x1,x2)-1<=px<=max(x1,x2)+1 and min(y1,y2)-1<=py<=max(y1,y2)+1 and min(x3,x4)-1<=px<=max(x3,x4)+1 and min(y3,y4)-1<=py<=max(y3,y4)+1:return px,py\n        return None\n\n    def draw_junctions(self):\n        lines=[o for o in self.objects if o.get('kind') in ('river','road')]\n        for i,a in enumerate(lines):\n            for b in lines[i+1:]:\n                if a.get('kind')!=b.get('kind'):continue\n                r=max(4,(a.get('width',25)+b.get('width',25))*.22*self.scale)\n                for sa,sb in self.line_segments(a):\n                    for sc,sd in self.line_segments(b):\n                        q=self.seg_intersection(sa,sb,sc,sd)\n                        if q:\n                            x,y=self.world_to_screen(*q);fill='#4fa8a2' if a.get('kind')=='river' else '#b79a70'\n                            self.canvas.create_oval(x-r,y-r,x+r,y+r,fill=fill,outline='')\n\n'''
s=s[:start]+draw+s[end:]
s=s.replace("if o['kind'] in ('river','road') and self._bbox_visible(o,rect):\n                self.draw_line_obj(o)\n        for o in self.objects:", "if o['kind'] in ('river','road') and self._bbox_visible(o,rect):\n                self.draw_line_obj(o)\n        self.draw_junctions()\n        for o in self.objects:")
old="self.objects.append({'id':self.oid(),'kind':self.tool,'points':self.stroke,'width':self.brush*.7 if self.tool=='river' else self.brush*.2});self.stroke=None;self.render();self.refresh()"
new="kind='river' if self.tool=='river' else 'road';pts=self.snap_line_endpoints(kind,self.stroke);obj={'id':self.oid(),'kind':kind,'points':pts,'width':self.brush*.7 if kind=='river' else self.brush*.2};\n            if kind=='road':obj['road_type']={'road_dirt':'Просёлочная','road_paved':'Мощенная','road_cobble':'Брусчаточная'}[self.tool]\n            self.objects.append(obj);self.stroke=None;self.render();self.refresh()"
s=s.replace(old,new)
s=s.replace("if o.get('kind') in ('river','road'):self.field('Толщина',round(o.get('width',25)),lambda v:self.num(o,'width',v))", "if o.get('kind') in ('river','road'):\n                self.field('Толщина',round(o.get('width',25)),lambda v:self.num(o,'width',v))\n                if o.get('kind')=='road':self.combo('Тип дороги',ROAD_TYPES,o.get('road_type','Просёлочная'),lambda v:self.val(o,'road_type',v))")
p.write_text(s,encoding='utf-8')